'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['runPipeline']);
const { runPipeline } = api;

(async () => {
  const emptySteps = [];
  const emptyPromise = runPipeline('seed', emptySteps);
  assert.ok(emptyPromise instanceof Promise);
  assert.strictEqual(await emptyPromise, 'seed');
  assert.deepStrictEqual(emptySteps, []);

  const order = [];
  const steps = [
    value => { order.push('one'); return value + 1; },
    value => new Promise(resolve => setTimeout(() => {
      order.push('two');
      resolve(value * 3);
    }, 5)),
    value => { order.push('three'); return { then: resolve => resolve(value - 2) }; },
    value => { order.push('four'); return value; }
  ];
  const snapshot = steps.slice();
  const promise = runPipeline(2, steps);
  assert.ok(promise instanceof Promise);
  assert.strictEqual(await promise, 7);
  assert.deepStrictEqual(order, ['one', 'two', 'three', 'four']);
  assert.deepStrictEqual(steps, snapshot);

  let invoked = false;
  const invalidPromise = runPipeline(0, [() => { invoked = true; }, 3]);
  assert.ok(invalidPromise instanceof Promise);
  await assert.rejects(invalidPromise, TypeError);
  assert.strictEqual(invoked, false);

  const syncError = new Error('sync failure');
  let later = false;
  await assert.rejects(runPipeline(1, [
    () => { throw syncError; },
    () => { later = true; }
  ]), error => error === syncError);
  assert.strictEqual(later, false);

  const rejection = new Error('rejected');
  later = false;
  await assert.rejects(runPipeline(1, [
    value => Promise.resolve(value + 1),
    () => Promise.reject(rejection),
    () => { later = true; }
  ]), error => error === rejection);
  assert.strictEqual(later, false);

  await assert.rejects(runPipeline(1, null), TypeError);
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

